const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const API=(window.B4_API_URL||'').replace(/\/$/,'');
const S={lang:localStorage.b4Lang||'en',theme:localStorage.b4Theme||'light',view:'dashboard',me:null,linked:[],students:[],teachers:[],subjects:[],schedule:[],assignments:[],resources:[],exams:[],announcements:[],messages:[],attendance:[],developers:[],badges:[],accounts:[],permissions:[],users:[],teacherMessages:[],notifications:[],examReview:null,error:''};
const L={en:{dashboard:'Dashboard',students:'Students',teachers:'Teachers',subjects:'Subjects',schedule:'Schedule',assignments:'Assignments',resources:'Resources',exams:'Exam Center',announcements:'Announcements',chat:'Class Chat',teacherChat:'Teacher Chat',attendance:'Attendance',admin:'Admin Center',teacherCenter:'Teacher Center',settings:'Settings',developers:'Developers',login:'Login',logout:'Log out',activate:'Activation Key',ai:'B4 AI',search:'Search everything...',guest:'Guest',save:'Save',add:'Add',edit:'Edit',delete:'Delete',open:'Open resource',light:'Light mode',dark:'Dark mode'},ar:{dashboard:'الرئيسية',students:'الطلاب',teachers:'المدرسين',subjects:'المواد',schedule:'الجدول',assignments:'الواجبات',resources:'المصادر',exams:'الامتحانات',announcements:'الإعلانات',chat:'شات الفصل',teacherChat:'شات المدرسين',attendance:'الحضور',admin:'مركز الإدارة',teacherCenter:'مركز المدرس',settings:'الإعدادات',developers:'المطورون',login:'تسجيل الدخول',logout:'تسجيل الخروج',activate:'مفتاح التفعيل',ai:'مساعد B4',search:'ابحث...',guest:'زائر',save:'حفظ',add:'إضافة',edit:'تعديل',delete:'حذف',open:'فتح المصدر',light:'الوضع النهاري',dark:'الوضع الليلي'}};
const t=k=>L[S.lang][k]||k;
const PERMS=[['MANAGE_CHAT','Manage Chat'],['MANAGE_ACCOUNTS','Manage Accounts'],['MANAGE_PERMISSIONS','Manage Permissions'],['VIEW_LOGS','View Logs'],['VIEW_ADMIN_CENTER','View Admin Center'],['MANAGE_STUDENTS','Manage Students'],['MANAGE_TEACHERS','Manage Teachers'],['MANAGE_ROLES','Manage Roles'],['MANAGE_ADMINS','Manage Admins'],['MANAGE_BADGES','Manage badges'],['MANAGE_SUBJECTS','Manage subjects'],['MANAGE_SCHEDULE','Manage schedule'],['MANAGE_ASSIGNMENTS','Manage assignments'],['MANAGE_RESOURCES','Manage resources'],['MANAGE_EXAMS','Manage exams'],['MANAGE_ANNOUNCEMENTS','Manage announcements'],['MANAGE_ATTENDANCE','Manage attendance'],['MANAGE_CHAT','Manage class chat'],['MANAGE_TEACHER_CHAT','Teacher chat'],['VIEW_LOGS','View logs'],['MANAGE_ANALYTICS','Attendance analytics'],['USE_AI','Use AI'],['MANAGE_DEVELOPERS','Manage developers'],['ADMINISTRATOR','Administrator']];
const api=async(path,opt={})=>{const r=await fetch(API+path,{credentials:'include',...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'Request failed');return d};
const toast=m=>{const e=document.createElement('div');e.className='toast';e.textContent=m;document.body.append(e);setTimeout(()=>e.remove(),2500)};
const close=()=>{$('#back')?.classList.remove('show')};window.b4Close=close;
const modal=h=>{$('#modal').innerHTML='<div class="modal">'+h+'</div>';$('#back').classList.add('show')};
const can=p=>{if(!S.me)return false;if(Number(S.me.is_super_admin)===1||S.me.role==='SUPER_ADMIN')return true;return (S.me.permissions||[]).includes(p)};
const nav=[['dashboard','⌂'],['students','♙'],['teachers','♟'],['subjects','▣'],['schedule','◫'],['assignments','✓'],['resources','▤'],['exams','⌁'],['announcements','◈'],['chat','◌'],['attendance','◉']];
function go(v){if(!S.me&&!['students','teachers','subjects','schedule'].includes(v)){loginModal();return}S.view=v;render();window.scrollTo({top:0,behavior:'smooth'});$('#side')?.classList.remove('open')}
function buildNav(){if(!S.me)return nav.filter(x=>['students','teachers','subjects','schedule'].includes(x[0])).map(x=>'<button data-v="'+x[0]+'" class="'+(S.view===x[0]?'active':'')+'">'+x[1]+' <span>'+t(x[0])+'</span></button>').join('');
let a=nav.map(x=>'<button data-v="'+x[0]+'" class="'+(S.view===x[0]?'active':'')+'">'+x[1]+' <span>'+t(x[0])+'</span></button>').join('');
if(S.me.role==='TEACHER'||can('MANAGE_ASSIGNMENTS'))a+='<button data-v="teacherCenter" class="'+(S.view==='teacherCenter'?'active':'')+'">◈ <span>'+t('teacherCenter')+'</span></button>';
if(can('MANAGE_TEACHER_CHAT')||S.me.role==='TEACHER'||S.me.role==='SUPER_ADMIN')a+='<button data-v="teacherChat" class="'+(S.view==='teacherChat'?'active':'')+'">☷ <span>'+t('teacherChat')+'</span></button>';
if(can('VIEW_ADMIN_CENTER'))a+='<button data-v="admin" class="'+(S.view==='admin'?'active':'')+'">⚙ <span>'+t('admin')+'</span></button>';
a+='<button data-v="settings" class="'+(S.view==='settings'?'active':'')+'">⚙ <span>'+t('settings')+'</span></button>';if(Number(S.me.is_super_admin)===1||S.me.role==='SUPER_ADMIN')a+='<button data-v="developers" class="'+(S.view==='developers'?'active':'')+'">⌘ <span>'+t('developers')+'</span></button>';return a}
function title(h,p,b=''){return '<div class="title"><div><div class="eyebrow">B4 • TELECOMMUNICATION</div><h1>'+h+'</h1><p>'+p+'</p></div><div class="actions">'+b+'</div></div>'}
function dashboard(){return title('Welcome to B4 👋','Your class, academics and communication in one place.',S.me?'<button class="btn primary" onclick="aiModal()">✦ '+t('ai')+'</button>':'<button class="btn primary" onclick="loginModal()">'+t('login')+'</button>')+
'<div class="hero"><div><span class="eyebrow">WE SCHOOL • B4</span><h1>B4 Telecommunication</h1><p>Official class portal for students and teachers.</p><button class="btn" onclick="aiModal()">✦ Ask B4 AI</button></div></div>'+
'<div class="grid stats"><div class="card stat"><small>Students</small><b>'+S.students.length+'</b></div><div class="card stat"><small>Teachers</small><b>'+S.teachers.length+'</b></div><div class="card stat"><small>Subjects</small><b>'+S.subjects.length+'</b></div><div class="card stat"><small>Assignments</small><b>'+S.assignments.length+'</b></div></div>'+
'<div class="grid c2"><div class="card"><div class="head"><h3>'+t('announcements')+'</h3>'+ (S.me?'<button class="btn ghost" onclick="go(\'announcements\')">View</button>':'')+'</div>'+(!S.me?'<p class="muted">Log in as a B4 student or teacher to see class announcements.</p>':S.announcements.slice(0,5).map(a=>'<div class="item"><div class="grow"><b>'+esc(a.title)+'</b><p class="muted">'+esc(a.body||'')+'</p></div></div>').join('')||'<div class="empty">No announcements.</div>')+'</div>'+
'<div class="card"><div class="head"><h3>✦ '+t('ai')+'</h3><span class="badge">ONLINE</span></div><p class="muted">AI is visible to everyone, but only B4 accounts can use it.</p><button class="btn primary" onclick="aiModal()">Open AI</button></div></div>'}
function peopleCard(x,type){return '<article class="card"><div class="item" style="padding:0;border:0"><img class="avatar" src="'+esc(x.avatar_url||'assets/logo.svg')+'"><div class="grow"><b>'+esc(x.display_name||x.official_name||'')+'</b><small class="muted">'+esc(type==='student'?x.student_code||'':x.teacher_code||'')+'</small></div><span class="badge">'+type+'</span></div>'+(can(type==='student'?'MANAGE_STUDENTS':'MANAGE_TEACHERS')?'<div class="actions-row"><button class="btn ghost" onclick="'+(type==='student'?'studentEdit('+x.id+')':'teacherEdit('+x.id+')')+'">Edit</button><button class="btn danger" onclick="'+(type==='student'?'studentDelete('+x.id+')':'teacherDelete('+x.id+')')+'">Delete</button></div>':'')+'</article>'}
function studentsV(){return title(t('students'),'B4 student directory.',can('MANAGE_STUDENTS')?'<button class="btn primary" onclick="studentEdit()">＋ '+t('add')+'</button>':'')+'<div class="grid c3">'+S.students.map(x=>peopleCard(x,'student')).join('')+'</div>'}
function teachersV(){return title(t('teachers'),'B4 teacher directory.',can('MANAGE_TEACHERS')?'<button class="btn primary" onclick="teacherEdit()">＋ '+t('add')+'</button>':'')+'<div class="grid c3">'+S.teachers.map(x=>peopleCard(x,'teacher')).join('')+'</div>'}
function subjectsV(){return title(t('subjects'),'Subjects and resources. '+(can('MANAGE_SUBJECTS')?'You can manage them from here.':''),can('MANAGE_SUBJECTS')?'<button class="btn primary" onclick="subjectEdit()">＋ '+t('add')+'</button>':'')+'<div class="grid c3">'+S.subjects.map(s=>'<article class="card"><div class="head"><h3>'+esc(s.name)+'</h3><span class="badge">'+(s.progress||0)+'%</span></div><p class="muted">'+esc(s.teacher_name||'')+'</p><div class="barline"><span style="width:'+(s.progress||0)+'%"></span></div><button class="btn ghost" onclick="go(\'resources\')">'+t('open')+' →</button>'+(can('MANAGE_SUBJECTS')?'<div class="actions-row"><button class="btn ghost" onclick="subjectEdit('+s.id+')">Edit</button><button class="btn danger" onclick="subjectDelete('+s.id+')">Delete</button></div>':'')+'</article>').join('')||'<div class="card empty">No subjects.</div>'+'</div>'}
function scheduleV(){return title(t('schedule'),'Official B4 schedule.',can('MANAGE_SCHEDULE')?'<button class="btn primary" onclick="scheduleEdit()">Edit schedule</button>':'')+'<div class="card tablewrap"><table class="table"><thead><tr><th>DAY</th><th>P1</th><th>P2</th><th>P3</th><th>P4</th></tr></thead><tbody>'+S.schedule.map(r=>'<tr><td><b>'+esc(r.day_name)+'</b></td><td>'+esc(r.p1||'—')+'</td><td>'+esc(r.p2||'—')+'</td><td>'+esc(r.p3||'—')+'</td><td>'+esc(r.p4||'—')+'</td></tr>').join('')+'</tbody></table></div>'}
function tasksV(){return title(t('assignments'),'Assignments and deadlines.',can('MANAGE_ASSIGNMENTS')?'<button class="btn primary" onclick="assignmentEdit()">＋ '+t('add')+'</button>':'')+'<div class="grid c2">'+S.assignments.map(a=>'<article class="card"><div class="head"><h3>'+esc(a.title)+'</h3><span class="badge">'+esc(a.status||'OPEN')+'</span></div><p class="muted">'+esc(a.subject_name||'')+'</p><p>'+esc(a.description||'')+'</p><div class="meter"><span>Deadline</span><b>'+esc(a.due_at||'—')+'</b></div>'+(can('MANAGE_ASSIGNMENTS')?'<div class="actions-row"><button class="btn ghost" onclick="assignmentEdit('+a.id+')">Edit</button><button class="btn danger" onclick="delAPI(\'/api/admin/assignments/'+a.id+'\',\'Assignment deleted\')">Delete</button></div>':'')+'</article>').join('')||'<div class="card empty">No assignments.</div>'+'</div>'}
function resourcesV(){return title(t('resources'),'Lessons, links and PDFs.',can('MANAGE_RESOURCES')?'<button class="btn primary" onclick="resourceEdit()">＋ '+t('add')+'</button>':'')+'<div class="grid c3">'+S.resources.map(r=>'<article class="card"><span class="badge">'+esc(r.resource_type||'RESOURCE')+'</span><h3>'+esc(r.title)+'</h3><p class="muted">'+esc(r.description||'')+'</p>'+(r.url||r.file_url?'<a class="btn primary" href="'+esc(r.url||r.file_url)+'" target="_blank" rel="noopener">'+t('open')+' →</a>':'')+(can('MANAGE_RESOURCES')?'<div class="actions-row"><button class="btn ghost" onclick="resourceEdit('+r.id+')">Edit</button><button class="btn danger" onclick="delAPI(\'/api/admin/resources/'+r.id+'\',\'Resource deleted\')">Delete</button></div>':'')+'</article>').join('')||'<div class="card empty">No resources.</div>'+'</div>'}
function examsV(){return title(t('exams'),'Exams, submissions and results.',can('MANAGE_EXAMS')?'<button class="btn primary" onclick="examEdit()">＋ '+t('add')+'</button>':'')+'<div class="grid c2">'+S.exams.map(e=>'<article class="card"><div class="head"><span class="badge">'+esc(e.status)+'</span><span class="muted">'+esc(e.subject_name||'')+'</span></div><h3>'+esc(e.title)+'</h3><p class="muted">'+esc(e.description||'')+'</p><div class="meter"><span>Starts</span><b>'+esc(e.starts_at||'Now')+'</b></div><div class="actions-row"><button class="btn primary" onclick="startExam('+e.id+')">Open</button>'+(can('MANAGE_EXAMS')?'<button class="btn ghost" onclick="examEdit('+e.id+')">Edit</button><button class="btn danger" onclick="delAPI(\'/api/admin/exams/'+e.id+'\',\'Exam deleted\')">Delete</button><button class="btn ghost" onclick="submissions('+e.id+')">Submissions</button>':'')+'</div></article>').join('')||'<div class="card empty">No exams.</div>'+'</div>'}
function announcementsV(){return title(t('announcements'),'Official class announcements.',can('MANAGE_ANNOUNCEMENTS')?'<button class="btn primary" onclick="announcementEdit()">＋ '+t('add')+'</button>':'')+'<div class="grid">'+S.announcements.map(a=>'<article class="card"><div class="head"><span class="badge">'+esc(a.category||'General')+'</span><small>'+esc(a.created_at||'')+'</small></div><h3>'+esc(a.title)+'</h3><p>'+esc(a.body||'')+'</p>'+(can('MANAGE_ANNOUNCEMENTS')?'<div class="actions-row"><button class="btn ghost" onclick="announcementEdit('+a.id+')">Edit</button><button class="btn danger" onclick="delAPI(\'/api/admin/announcements/'+a.id+'\',\'Announcement deleted\')">Delete</button></div>':'')+'</article>').join('')+'</div>'}
function chatV(){return title(t('chat'),'Live class chat.')+'<div class="card chat"><div class="messages" id="messages">'+S.messages.map(messageHTML).join('')+'</div><div id="typing" class="typing-indicator"></div><form class="chatform" onsubmit="sendChat(event)"><input id="chatInput" oninput="typing(!!this.value.trim())" placeholder="Write a message..."><button class="btn primary">➤</button></form></div>'}
function messageHTML(m){
  const reply=m.reply_to_id?'<div class="reply-preview"><b>↩ '+esc(m.reply_display_name||'Reply')+'</b><span>'+esc(m.reply_body||'')+'</span></div>':'';
  const edited=m.edited_at?'<small class="edited">edited</small>':'';
  return '<div class="msg '+(S.me&&Number(m.user_id)===Number(S.me.id)?'me':'')+'" onclick="messageMenu(event,'+m.id+')"><img class="avatar" src="'+esc(m.avatar_url||'assets/logo.svg')+'"><div><b>'+esc(m.display_name||'Deleted user')+'</b>'+reply+'<div class="bubble">'+esc(m.body||'')+edited+'</div><small class="muted">'+esc(m.created_at||'')+'</small></div></div>'
}
function attendanceV(){if(!can('MANAGE_ATTENDANCE'))return title(t('attendance'),'Your attendance record.')+'<div class="card"><p>Attendance management is available to authorized staff.</p></div>';return title(t('attendance'),'Mark attendance and view analysis.','<button class="btn primary" onclick="attendanceLoad()">Refresh</button>')+'<div id="attendanceRoot"></div>'}
function adminV(){const cards=[['roles','Roles','MANAGE_ROLES'],['permissions','Permissions','MANAGE_PERMISSIONS'],['accounts','Accounts','MANAGE_ACCOUNTS'],['students','Manage Students','MANAGE_STUDENTS'],['teachers','Manage Teachers','MANAGE_TEACHERS'],['keys','Activation Keys','MANAGE_KEYS'],['badges','Manage Badges','MANAGE_BADGES'],['subjects','Manage Subjects','MANAGE_SUBJECTS'],['schedule','Manage Schedule','MANAGE_SCHEDULE'],['admins','Manage Admins','MANAGE_ADMINS'],['logs','View Logs','VIEW_LOGS'],['attendance','Attendance','MANAGE_ATTENDANCE']];if(Number(S.me?.is_super_admin)===1||S.me?.role==='SUPER_ADMIN')cards.push(['developers','Manage Developers','MANAGE_DEVELOPERS']);return title(t('admin'),'Control center — permissions are separate from Student/Teacher role.')+'<div class="grid c3 admin-cards">'+cards.filter(x=>can(x[2])).map(x=>'<button class="card admin-card" onclick="go(\'admin:'+x[0]+'\')"><span>◈</span><h3>'+x[1]+'</h3><small>Open management</small></button>').join('')+'</div>'}
function teacherCenterV(){return title(t('teacherCenter'),'Teacher tools — not an Admin Center.')+'<div class="grid c3">'+[['assignments','Create assignments','MANAGE_ASSIGNMENTS'],['resources','Publish resources/PDFs','MANAGE_RESOURCES'],['exams','Create exams','MANAGE_EXAMS'],['announcements','Publish announcements','MANAGE_ANNOUNCEMENTS'],['subjects','Manage teaching subjects','MANAGE_SUBJECTS'],['schedule','View schedule','VIEW_CLASS']].filter(x=>can(x[2])).map(x=>'<button class="card admin-card" onclick="go(\''+x[0]+'\')"><span>✦</span><h3>'+x[1]+'</h3></button>').join('')+'</div>'}
function settingsV(){
  const ar=S.lang==='ar';
  return title(t('settings'),ar?'الحساب واللغة والمظهر وربط Google.':'Account, language, theme and Google linking.')+
  '<div class="grid c2"><div class="card"><h3>'+ (ar?'الملف الشخصي':'Profile') +'</h3><form class="form" onsubmit="saveProfile(event)"><label>'+ (ar?'اسم العرض':'Display name') +'<input id="displayName" value="'+esc(S.me?.display_name||'')+'" required></label><label>'+ (ar?'صورة الملف الشخصي':'Profile image') +'<input id="profileAvatar" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="btn primary">'+t('save')+'</button></form><button class="btn ghost" onclick="passwordModal()">'+(ar?'تغيير كلمة المرور':'Change password')+'</button><button class="btn danger" onclick="logout()"> '+t('logout')+'</button></div>'+
  '<div class="card"><h3>'+ (ar?'التفضيلات':'Preferences') +'</h3><div class="settings-lang"><button class="btn '+(S.lang==='en'?'primary':'ghost')+'" onclick="setLang(\'en\')">EN</button><button class="btn '+(S.lang==='ar'?'primary':'ghost')+'" onclick="setLang(\'ar\')">عربي</button></div><button class="btn ghost" onclick="toggleTheme()">'+(S.theme==='dark'?t('light'):t('dark'))+'</button><hr><h3>Google</h3><p class="muted">'+(S.linked.length?(ar?'Google مرتبط':'Google linked'):(ar?'Google غير مرتبط':'Google not linked'))+'</p><button class="btn primary" onclick="googleLink()">'+(S.linked.length?(ar?'إعادة ربط Google':'Relink Google'):(ar?'ربط Google':'Link Google'))+'</button>'+(S.linked.length?'<button class="btn danger" onclick="unlinkGoogle()">'+(ar?'إلغاء ربط Google':'Unlink Google')+'</button>':'')+'</div></div>';
}
function devV(){return title(t('developers'),'The B4 development team and project contributors.')+'<div class="grid developers-grid">'+S.developers.map(d=>'<article class="card developer-card"><div class="developer-photo"><img class="avatar xl" src="'+esc(d.avatar_url||'assets/logo.svg')+'" onerror="this.src=\'assets/logo.svg\'"></div><div class="developer-info"><span class="badge">B4 DEVELOPER</span><h3>'+esc(d.name)+'</h3>'+(d.link_url?'<a class="btn ghost developer-link" href="'+esc(d.link_url)+'" target="_blank" rel="noopener">Open profile ↗</a>':'')+'</div></article>').join('')||'<div class="card empty">No developers added yet.</div>'+'</div>'}
function render(){document.documentElement.dataset.theme=S.theme;document.documentElement.classList.toggle('dark',S.theme==='dark');document.documentElement.lang=S.lang;document.documentElement.dir=S.lang==='ar'?'rtl':'ltr';if(window.chatStream){window.chatStream.close();window.chatStream=null}$('#nav').innerHTML=buildNav();let v=S.view;let html=v==='dashboard'?dashboard():v==='students'?studentsV():v==='teachers'?teachersV():v==='subjects'?subjectsV():v==='schedule'?scheduleV():v==='assignments'?tasksV():v==='resources'?resourcesV():v==='exams'?examsV():v==='announcements'?announcementsV():v==='chat'?chatV():v==='teacherChat'?teacherChatV():v==='attendance'?attendanceV():v==='admin'?adminV():v==='teacherCenter'?teacherCenterV():v==='settings'?settingsV():v==='developers'?devV():v==='exam-review'?examReviewV():v.startsWith('admin:')?adminPage(v.slice(6)):dashboard();$('#content').innerHTML=html;$('#topName').textContent=S.me?.display_name||t('guest');if(S.me?.avatar_url)$('#topAvatar').src=S.me.avatar_url;if(v==='attendance'&&can('MANAGE_ATTENDANCE'))attendanceLoad();if(v==='chat')chatLoop();if(v==='teacherChat')teacherChatLoop();if(v.startsWith('admin:'))adminLoad(v.slice(6))}
function teacherChatV(){return title(t('teacherChat'),'Private chat for teachers and authorized staff.')+'<div class="card chat"><div class="messages" id="teacherMessages">'+S.teacherMessages.map(m=>messageHTML(m)).join('')+'</div><div id="teacherTyping" class="typing-indicator"></div><form class="chatform" onsubmit="sendTeacherChat(event)"><input id="teacherInput" oninput="teacherTyping(!!this.value.trim())"><button class="btn primary">➤</button></form></div>'}
function adminPage(p){if(p==='roles')return title('Roles','Account role is only Student or Teacher. Super Admin is a private system flag, never a role.')+'<div id="adminRoot"></div>';if(p==='permissions')return title('Permissions','Direct permissions are independent from the account role. Administrator grants every permission.')+'<div id="adminRoot"></div>';if(p==='accounts')return title('Accounts','Activation key, Google link, password and sessions.')+'<div id="adminRoot"></div>';if(p==='students')return title('Manage Students','Edit identity, display name and photo.','<button class="btn primary" onclick="studentEdit()">＋ Add</button>')+'<div class="grid c3">'+S.students.map(x=>peopleCard(x,'student')).join('')+'</div>';if(p==='teachers')return title('Manage Teachers','Edit identity, display name and photo.','<button class="btn primary" onclick="teacherEdit()">＋ Add</button>')+'<div class="grid c3">'+S.teachers.map(x=>peopleCard(x,'teacher')).join('')+'</div>';if(p==='keys')return title('Activation Keys','One-time keys.')+'<div id="adminRoot"></div>';if(p==='badges')return title('Manage Badges','Create icons and assign badges.')+'<div id="adminRoot"></div>';if(p==='subjects')return subjectsV();if(p==='schedule')return scheduleV();if(p==='admins')return title('Manage Admins','Admin access is independent from Student/Teacher role.')+'<div id="adminRoot"></div>';if(p==='logs')return title('Logs','All platform activity and security events.')+'<div id="adminRoot"></div>';if(p==='attendance')return attendanceV();if(p==='developers')return title('Manage Developers','Super Admin only.')+'<div id="adminRoot"></div>';return adminV()}
async function loadMe(){try{const d=await api('/api/auth/me');S.me=d.user;S.linked=(await api('/api/auth/linked')).linked||[]}catch{S.me=null;S.linked=[]}await loadData();render()}
async function loadData(){try{const d=await api('/api/bootstrap');Object.assign(S,{students:d.students||[],teachers:d.teachers||[],subjects:d.subjects||[],schedule:d.schedule||[],assignments:d.assignments||[],announcements:d.announcements||[],resources:d.resources||[],exams:d.exams||[],attendance:d.attendance||[],messages:d.messages||[],notifications:d.notifications||[]});if(S.me&&(Number(S.me.is_super_admin)===1||S.me.role==='SUPER_ADMIN')){try{S.developers=(await api('/api/admin/developers')).developers||[]}catch{}}S.error=''}catch(e){S.error=e.message}}
async function login(e){e.preventDefault();try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({login:$('#loginName').value.trim(),password:$('#loginPassword').value})});close();await loadMe();toast('Login successful ✓')}catch(x){toast(x.message)}}
function loginModal(){modal('<div class="modalhead"><h2>'+t('login')+'</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="login(event)"><label>Display name<input id="loginName" required autocomplete="username"></label><label>Password<input id="loginPassword" type="password" required autocomplete="current-password"></label><button class="btn primary">'+t('login')+' →</button></form><div class="login-divider"><span>or</span></div><button class="google-btn" onclick="googleLogin()">Continue with Google</button><button class="btn ghost" onclick="forgotPassword()">Forgot my password</button><button class="btn ghost" onclick="activationModal()">'+t('activate')+'</button>')}
function activationModal(){modal('<div class="modalhead"><h2>'+t('activate')+'</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="activate(event)"><label>One-time key<input id="actKey" required></label><label>Display name<input id="actName" required></label><label>Password<input id="actPw" type="password" minlength="8" required></label><button class="btn primary">Create account</button></form>')}
async function activate(e){e.preventDefault();try{await api('/api/auth/activate',{method:'POST',body:JSON.stringify({key:$('#actKey').value.trim(),displayName:$('#actName').value.trim(),password:$('#actPw').value})});close();toast('Account created ✓');loginModal()}catch(x){toast(x.message)}}
function googleLogin(){location.href=API+'/api/auth/google/login'}
async function openNotifications(){try{const d=await api('/api/bootstrap');const list=d.notifications||[];modal('<div class="modalhead"><h2>Notifications</h2><button class="close" onclick="b4Close()">×</button></div><div class="list">'+(list.length?list.map(n=>'<div class="item"><span class="grow"><b>'+esc(n.title)+'</b><small class="muted">'+esc(n.body||'')+'</small></span><small class="muted">'+esc(n.created_at||'')+'</small></div>').join(''):'<div class="empty">No notifications.</div>')+'</div>')}catch(e){toast(e.message)}}
async function forgotPassword(){try{const d=await api('/api/auth/forgot-password',{method:'POST'});location.href=d.whatsapp}catch(e){toast('WhatsApp support is unavailable')}} 
function passwordModal(){modal('<div class="modalhead"><h2>Change password</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="changePassword(event)"><label>Current password<input id="oldPw" type="password" required></label><label>New password<input id="newPw" type="password" minlength="8" required></label><button class="btn primary">Save</button></form>')}
async function changePassword(e){e.preventDefault();try{await api('/api/auth/password',{method:'POST',body:JSON.stringify({currentPassword:$('#oldPw').value,newPassword:$('#newPw').value})});close();toast('Password changed ✓')}catch(x){toast(x.message)}}
async function saveProfile(e){e.preventDefault();try{await api('/api/auth/profile',{method:'PATCH',body:JSON.stringify({displayName:$('#displayName').value.trim()})});const f=$('#profileAvatar')?.files?.[0];if(f){const fd=new FormData();fd.append('file',f);const r=await fetch(API+'/api/auth/avatar',{method:'POST',credentials:'include',body:fd});if(!r.ok)throw Error('Image upload failed')}await loadMe();toast('Saved ✓')}catch(x){toast(x.message)}}
async function logout(){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});S.me=null;S.view='students';await loadData();render();toast('Logged out')}
function googleLink(){location.href=API+'/api/auth/google/start'}async function unlinkGoogle(){try{await api('/api/auth/linked/GOOGLE',{method:'DELETE'});await loadMe()}catch(e){toast(e.message)}}
function aiModal(){modal('<div class="modalhead"><h2>✦ '+t('ai')+'</h2><button class="close" onclick="b4Close()">×</button></div><div id="aiOut" class="card">Ask a study question.</div><form class="form" onsubmit="askAI(event)"><textarea id="aiInput" rows="4" placeholder="Ask about Telecommunication..."></textarea><button class="btn primary">Send</button></form>')}
async function askAI(e){e.preventDefault();if(!S.me||S.me.role!=='STUDENT'){toast('لازم تكون طالب في B4 عشان تستخدم الـAI');return}try{$('#aiOut').textContent='Thinking…';const d=await api('/api/ai',{method:'POST',body:JSON.stringify({message:$('#aiInput').value})});$('#aiOut').textContent=d.answer}catch(x){toast(x.message)}}
function chatLoop(){clearInterval(window.chatTimer);clearInterval(window.chatTypingTimer);if(window.chatStream){window.chatStream.close();window.chatStream=null}if(!S.me||S.view!=='chat')return;try{window.chatStream=new EventSource(API+'/api/chat/stream',{withCredentials:true});window.chatStream.addEventListener('message',e=>{try{const d=JSON.parse(e.data);if(d.type==='created'&&!S.messages.some(m=>Number(m.id)===Number(d.message.id)))S.messages.push(d.message);else if(d.type==='updated')S.messages=S.messages.map(m=>Number(m.id)===Number(d.message.id)?d.message:m);else if(d.type==='deleted')S.messages=S.messages.filter(m=>Number(m.id)!==Number(d.id));const box=$('#messages');if(box){box.innerHTML=S.messages.map(messageHTML).join('');box.scrollTop=box.scrollHeight}}catch{}});window.chatStream.onerror=()=>{};window.chatTypingTimer=setInterval(async()=>{if(S.view!=='chat')return;try{const ty=await api('/api/chat/typing');const el=$('#typing');if(el)el.textContent=(ty.users||[]).filter(x=>Number(x.user_id)!==Number(S.me.id)).map(x=>x.display_name+' is typing…').join(' • ')}catch{}},1200);}catch{}}async function sendChat(e){
  e.preventDefault();const i=$('#chatInput');if(!i.value.trim())return;
  try{
    await api('/api/chat/messages',{method:'POST',body:JSON.stringify({body:i.value.trim(),replyToId:window.replyTo||null})});
    i.value='';i.placeholder='Write a message...';window.replyTo=null;typing(false);toast('Message sent ✓');
  }catch(x){toast(x.message)}
}
function typing(v){if(!S.me)return;api('/api/chat/typing',{method:'POST',body:JSON.stringify({typing:v})}).catch(()=>{});if(window.typingT)clearTimeout(window.typingT);if(v)window.typingT=setTimeout(()=>typing(false),1600)}
function messageMenu(e,id){e.preventDefault();if(!S.me)return;const m=S.messages.find(x=>Number(x.id)===Number(id));if(!m)return;modal('<div class="modalhead"><h2>Message</h2><button class="close" onclick="b4Close()">×</button></div><button class="btn ghost" onclick="replyMessage('+id+')">Reply</button>'+(Number(m.user_id)===Number(S.me.id)?'<button class="btn ghost" onclick="editMessage('+id+')">Edit</button><button class="btn danger" onclick="deleteMessage('+id+')">Delete</button>':'')+'<button class="btn ghost" onclick="b4Close()">Close</button>')}
function replyMessage(id){const m=S.messages.find(x=>Number(x.id)===Number(id));close();window.replyTo=id;const input=$('#chatInput');if(input){input.value='';input.placeholder='Replying to '+(m?.display_name||'message')+'…';input.focus();}toast('Reply mode enabled')}
async function editMessage(id){const m=S.messages.find(x=>Number(x.id)===Number(id));if(!m)return;modal('<div class="modalhead"><h2>Edit message</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="saveMessage(event,'+id+')"><textarea id="editMsg" rows="4">'+esc(m.body)+'</textarea><button class="btn primary">Save</button></form>')}
async function saveMessage(e,id){e.preventDefault();try{await api('/api/chat/messages/'+id,{method:'PATCH',body:JSON.stringify({body:$('#editMsg').value})});close();toast('Message updated ✓')}catch(x){toast(x.message)}}
async function deleteMessage(id){if(!confirm('Delete message?'))return;try{await api('/api/chat/messages/'+id,{method:'DELETE'});close();toast('Message deleted ✓')}catch(x){toast(x.message)}}
function teacherChatLoop(){clearInterval(window.teacherTimer);window.teacherTimer=setInterval(async()=>{if(S.view!=='teacherChat')return;try{const d=await api('/api/teacher-chat/messages');S.teacherMessages=d.messages||[];const b=$('#teacherMessages');if(b){b.innerHTML=S.teacherMessages.map(messageHTML).join('');b.scrollTop=b.scrollHeight}const ty=await api('/api/teacher-chat/typing');$('#teacherTyping').textContent=(ty.users||[]).filter(x=>Number(x.user_id)!==Number(S.me.id)).map(x=>x.display_name+' is typing…').join(' • ')}catch{}},1000)}
async function sendTeacherChat(e){e.preventDefault();const i=$('#teacherInput');if(!i.value.trim())return;try{await api('/api/teacher-chat/messages',{method:'POST',body:JSON.stringify({body:i.value.trim()})});i.value='';const d=await api('/api/teacher-chat/messages');S.teacherMessages=d.messages||[];render()}catch(x){toast(x.message)}}
function teacherTyping(v){api('/api/teacher-chat/typing',{method:'POST',body:JSON.stringify({typing:v})}).catch(()=>{})}
async function attendanceLoad(){if(!can('MANAGE_ATTENDANCE'))return;const root=$('#attendanceRoot');if(!root)return;const date=new Date().toISOString().slice(0,10);try{const [d,a]=await Promise.all([api('/api/admin/attendance?date='+date),api('/api/attendance/analysis')]);root.innerHTML='<div class="card"><h3>'+date+'</h3><div class="grid c3"><div class="card"><b>'+Number(d.summary?.present_count||0)+'</b><small>Present</small></div><div class="card"><b>'+Number(d.summary?.absent_count||0)+'</b><small>Absent</small></div><div class="card"><b>'+Number(d.summary?.total_count||0)+'</b><small>Marked</small></div></div><h3>Attendance Analysis</h3><div class="analysis-list">'+(a.students||[]).map(s=>'<div class="analysis-row"><div><b>'+esc(s.display_name)+'</b><small>'+Number(s.present_days||0)+' present • '+Number(s.absent_days||0)+' absent</small></div><div class="analysis-bar"><span style="width:'+Number(s.present_rate||0)+'%"></span></div><strong>'+Number(s.present_rate||0)+'%</strong></div>').join('')+'</div><div class="list">'+d.students.map(s=>'<div class="item"><span class="grow"><b>'+esc(s.display_name)+'</b><small class="muted">'+esc(s.student_code||'')+'</small></span><button class="btn '+(s.status==='PRESENT'?'primary':'ghost')+'" onclick="markAttendance('+s.id+',\'PRESENT\')">Present</button><button class="btn '+(s.status==='ABSENT'?'danger':'ghost')+'" onclick="markAttendance('+s.id+',\'ABSENT\')">Absent</button></div>').join('')+'</div></div>'}catch(e){root.innerHTML='<div class="card notice">'+esc(e.message)+'</div>'}}async function markAttendance(id,status){try{await api('/api/admin/attendance',{method:'POST',body:JSON.stringify({userId:id,status,date:new Date().toISOString().slice(0,10)})});attendanceLoad();toast(status)}catch(e){toast(e.message)}}
function adminLoad(p){if(p==='roles')loadRoles();if(p==='permissions')loadPermissions();if(p==='accounts')loadAccounts();if(p==='keys')loadKeys();if(p==='badges')loadBadges();if(p==='admins')loadAdmins();if(p==='logs')loadLogs();if(p==='developers')loadDevelopers()}
async function loadRoles(){
  const r=$('#adminRoot');
  try{
    const d=await api('/api/admin/users');S.users=d.users||[];
    r.innerHTML='<div class="grid c2">'+S.users.map(u=>{
      const linked=u.role==='TEACHER'?(u.teacher_id?'Teacher profile #'+u.teacher_id:'Not linked'):(u.student_id?'Student profile #'+u.student_id:'Not linked');
      const options='<option value="STUDENT" '+(u.role==='STUDENT'?'selected':'')+'>STUDENT</option><option value="TEACHER" '+(u.role==='TEACHER'?'selected':'')+'>TEACHER</option>';
      return '<div class="card role-card"><div class="head"><div><b>'+esc(u.display_name)+'</b><p class="muted">'+esc(u.official_name||'')+'</p></div>'+(Number(u.is_super_admin)===1?'<span class="badge">SUPER ADMIN</span>':'<span class="badge">'+esc(u.role)+'</span>')+'</div><p class="muted">Current link: '+esc(linked)+'</p>'+ (Number(u.is_super_admin)===1?'<div class="notice">Super Admin is a private system flag. This account keeps its Student/Teacher role.</div>':'<label>Account role<select onchange="changeRole('+u.id+',this.value)">'+options+'</select></label>')+'</div>';
    }).join('')+'</div>';
  }catch(e){r.innerHTML='<div class="card notice">'+esc(e.message)+'</div>'}
}
async function loadPermissions(){
  const r=$('#adminRoot');
  try{const d=await api('/api/admin/users');S.users=d.users||[];
    r.innerHTML='<div class="grid c2">'+S.users.map(u=>'<div class="card permission-user" data-user-id="'+u.id+'"><div class="head"><div><b>'+esc(u.display_name)+'</b><p class="muted">'+esc(u.role)+'</p></div><span class="badge">'+(u.direct_permissions?.length||0)+' direct</span></div><div class="permission-grid">'+PERMS.map(p=>'<label class="permission-tile '+((u.direct_permissions||[]).includes(p[0])?'is-on':'')+'"><input type="checkbox" data-perm="'+p[0]+'" '+((u.direct_permissions||[]).includes(p[0])?'checked':'')+'><span>'+p[1]+'</span></label>').join('')+'</div><button class="btn primary" onclick="savePermissions('+u.id+')">Save permissions</button></div>').join('')+'</div>';
  }catch(e){r.innerHTML='<div class="card notice">'+esc(e.message)+'</div>'}
}
async function changeRole(id,role){
  const user=S.users.find(u=>Number(u.id)===Number(id));if(!user)return;
  if(role==='TEACHER'){
    const opts=S.teachers.map(x=>'<option value="'+x.id+'" '+(Number(x.id)===Number(user.teacher_id)?'selected':'')+'>'+esc(x.display_name)+' • '+esc(x.teacher_code||'')+'</option>').join('');
    modal('<div class="modalhead"><h2>Link Teacher Profile</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="saveRoleLink(event,'+id+',\'TEACHER\')"><p class="muted">Choose the teacher profile this account represents.</p><select id="roleLink">'+opts+'</select><button class="btn primary">Save Teacher role</button></form>');
  }else{
    const opts=S.students.map(x=>'<option value="'+x.id+'" '+(Number(x.id)===Number(user.student_id)?'selected':'')+'>'+esc(x.display_name)+' • '+esc(x.student_code||'')+'</option>').join('');
    modal('<div class="modalhead"><h2>Link Student Profile</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="saveRoleLink(event,'+id+',\'STUDENT\')"><p class="muted">Choose the student profile this account represents.</p><select id="roleLink">'+opts+'</select><button class="btn primary">Save Student role</button></form>');
  }
}
async function saveRoleLink(e,id,role){
  e.preventDefault();
  const linkId=Number($('#roleLink').value);
  try{
    const body=role==='TEACHER'?{role,teacherId:linkId}:{role,studentId:linkId};
    await api('/api/admin/users/'+id+'/role',{method:'PATCH',body:JSON.stringify(body)});
    close();await loadMe();await loadRoles();toast('Role and profile link updated ✓');
  }catch(e){toast(e.message)}
}
async function savePermissions(id){try{const card=[...document.querySelectorAll('.permission-user')].find(x=>x.dataset.userId===String(id));const codes=card?[...card.querySelectorAll('[data-perm]:checked')].map(x=>x.dataset.perm):[];await api('/api/admin/users/'+id+'/permissions',{method:'PUT',body:JSON.stringify({permissionCodes:codes})});toast('Permissions saved ✓');loadPermissions()}catch(e){toast(e.message)}}
async function loadAccounts(){
  const r=$('#adminRoot');
  try{
    const d=await api('/api/admin/accounts');
    r.innerHTML=`<div class="tablewrap"><table class="table"><thead><tr><th>Name</th><th>Role</th><th>Activation</th><th>Google</th><th>Session</th><th>Actions</th></tr></thead><tbody>
      ${(d.accounts||[]).map(a=>`<tr><td>${esc(a.display_name)}</td><td>${esc(a.role)}</td><td>${esc(a.activation_key_preview||a.identity_code||'—')}</td><td>${a.google_linked?'✓':'—'}</td><td>${esc(a.status)}</td><td><button class="btn ghost" onclick="resetAccount(${a.id})">Reset password</button><button class="btn ghost" onclick="endSession(${a.id})">End session</button><button class="btn danger" onclick="deleteAccount(${a.id})">Delete</button></td></tr>`).join('')}
    </tbody></table></div>`;
  }catch(e){r.innerHTML='<div class="card notice">'+esc(e.message)+'</div>'}
}
async function deleteAccount(id){
  if(!confirm('Delete this account permanently?'))return;
  try{await api('/api/admin/accounts/'+id,{method:'DELETE'});await loadData();loadAccounts();toast('Account deleted ✓')}catch(e){toast(e.message)}
}
async function resetAccount(id){try{const d=await api('/api/admin/accounts/'+id+'/reset-password',{method:'POST'});modal('<div class="modalhead"><h2>Temporary password</h2><button class="close" onclick="b4Close()">×</button></div><div class="notice"><b>'+esc(d.tempPassword)+'</b></div><p class="muted">Give it to the account owner and ask them to change it.</p>')}catch(e){toast(e.message)}}
async function endSession(id){try{await api('/api/admin/accounts/'+id+'/end-session',{method:'POST'});toast('Session ended ✓')}catch(e){toast(e.message)}}
async function loadKeys(){
  const r=$('#adminRoot');
  try{
    const d=await api('/api/admin/activation-keys');
    r.innerHTML=`<div class="head"><div><h3>Activation keys</h3><p class="muted">Copy and revoke keys.</p></div><button class="btn primary" onclick="createKey()">＋ Generate key</button></div>
      <div class="list">${(d.keys||[]).map(k=>`<div class="item key-row"><span class="grow"><b>${esc(k.key_value||k.key_preview)}</b><small>${esc(k.person_name||'')} • ${esc(k.person_type||'')}</small></span><span class="badge">${esc(k.status)}</span>${k.key_value?'<button class="btn ghost" onclick="copyKey('+k.id+')">Copy</button>':''}${k.status==='ACTIVE'?'<button class="btn danger" onclick="revokeKey('+k.id+')">Revoke</button>':''}</div>`).join('')||'<div class="card empty">No activation keys yet.</div>'}</div>`;
  }catch(e){r.innerHTML='<div class="card notice">'+esc(e.message)+'</div>'}
}
async function copyKey(id){
  try{const d=await api('/api/admin/activation-keys');const k=(d.keys||[]).find(x=>Number(x.id)===Number(id));if(!k?.key_value)return toast('This older key cannot be recovered');await navigator.clipboard.writeText(k.key_value);toast('Activation key copied ✓')}catch(e){toast(e.message)}
}
async function revokeKey(id){
  if(!confirm('Revoke this activation key?'))return;
  try{await api('/api/admin/activation-keys/'+id+'/revoke',{method:'POST'});loadKeys();toast('Key revoked ✓')}catch(e){toast(e.message)}
}
async function createKey(){try{const d=await api('/api/admin/people');const opts=[...d.students.map(x=>'<option value="STUDENT:'+x.id+'">'+esc(x.display_name)+'</option>'),...d.teachers.map(x=>'<option value="TEACHER:'+x.id+'">'+esc(x.display_name)+'</option>')].join('');modal('<div class="modalhead"><h2>Generate activation key</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="makeKey(event)"><select id="keyPerson">'+opts+'</select><button class="btn primary">Generate</button></form>')}catch(e){toast(e.message)}}
async function makeKey(e){e.preventDefault();const [personType,personId]=$('#keyPerson').value.split(':');try{const d=await api('/api/admin/activation-keys',{method:'POST',body:JSON.stringify({personType,personId:Number(personId)})});close();await navigator.clipboard?.writeText(d.key);modal('<div class="modalhead"><h2>Activation key</h2><button class="close" onclick="b4Close()">×</button></div><div class="notice mono">'+esc(d.key)+'</div>')}catch(x){toast(x.message)}}
async function loadBadges(){const r=$('#adminRoot');try{const d=await api('/api/admin/badges');S.badges=d.badges||[];r.innerHTML='<button class="btn primary" onclick="badgeCreate()">＋ Add badge</button><div class="grid c3">'+d.badges.map(b=>'<article class="card"><img class="avatar" src="/api/badges/'+b.id+'/icon"><h3>'+esc(b.name)+'</h3><p>'+esc(b.description||'')+'</p><button class="btn ghost" onclick="badgeAssign('+b.id+')">Assign</button></article>').join('')+'</div>'}catch(e){r.innerHTML='<div class="card notice">'+esc(e.message)+'</div>'}}
function badgeCreate(){modal('<div class="modalhead"><h2>New badge</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="makeBadge(event)"><input id="badgeName" placeholder="Badge name" required><input id="badgeDesc" placeholder="Description"><input id="badgeIcon" type="file" accept="image/*"><button class="btn primary">Create</button></form>')}
async function makeBadge(e){e.preventDefault();try{const d=await api('/api/admin/badges',{method:'POST',body:JSON.stringify({name:$('#badgeName').value,description:$('#badgeDesc').value})});const f=$('#badgeIcon').files[0];if(f){const fd=new FormData();fd.append('file',f);await fetch(API+'/api/admin/badges/'+d.id+'/icon',{method:'POST',credentials:'include',body:fd})}close();loadBadges()}catch(x){toast(x.message)}}
async function badgeAssign(bid){const d=await api('/api/admin/badges');const opts=d.people.map(p=>'<option value="'+p.id+'">'+esc(p.display_name)+' • '+p.role+'</option>').join('');modal('<div class="modalhead"><h2>Assign badge</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="doBadgeAssign(event,'+bid+')"><select id="badgeUser">'+opts+'</select><button class="btn primary">Assign</button></form>')}
async function doBadgeAssign(e,bid){e.preventDefault();try{await api('/api/admin/badges/assign',{method:'POST',body:JSON.stringify({userId:Number($('#badgeUser').value),badgeId:bid})});close();toast('Badge assigned ✓')}catch(x){toast(x.message)}}
async function loadAdmins(){const r=$('#adminRoot');const d=await api('/api/admin/users');r.innerHTML='<div class="grid c2">'+d.users.filter(u=>u.role!=='SUPER_ADMIN').map(u=>'<div class="card"><b>'+esc(u.display_name)+'</b><p class="muted">'+esc(u.role)+'</p><button class="btn primary" onclick="adminPermissions('+u.id+')">Manage admin access</button></div>').join('')+'</div><button class="btn ghost" onclick="adminPermissions()">Grant to a person</button>'}
async function adminPermissions(id){const d=await api('/api/admin/users');const opts=d.users.filter(u=>u.role!=='SUPER_ADMIN').map(u=>'<option value="'+u.id+'">'+esc(u.display_name)+' • '+u.role+'</option>').join('');modal('<div class="modalhead"><h2>Admin access</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="grantAdmin(event)"><select id="adminUser">'+opts+'</select><div class="permission-grid">'+PERMS.map(p=>'<label class="permission-tile"><input type="checkbox" name="ap" value="'+p[0]+'"><span>'+p[1]+'</span></label>').join('')+'</div><button class="btn primary">Save admin permissions</button></form>')}
async function grantAdmin(e){e.preventDefault();const id=Number($('#adminUser').value),codes=[...document.querySelectorAll('input[name="ap"]:checked')].map(x=>x.value);try{await api('/api/admin/users/'+id+'/permissions',{method:'PUT',body:JSON.stringify({permissionCodes:codes})});close();toast('Admin access saved ✓')}catch(x){toast(x.message)}}
