let examDraft=[];
function examInputDate(v){return v?String(v).replace(' ','T').slice(0,16):''}
function examDraftFromQuestion(q){return {questionText:q?.question_text||'',questionType:q?.question_type||'MCQ',options:Array.isArray(q?.options_json)?q.options_json:[],correctAnswer:q?.correct_answer||'',points:Number(q?.points||1)}}
function examQuestionHTML(q,i){
  const type=q.questionType||'MCQ';
  const options=(q.options||['Option A','Option B']).map(x=>String(x||''));
  const optionFields=type==='MCQ'?'<div class="answer-list">'+[0,1,2,3].map(j=>'<div class="answer-option"><input data-qopt="'+i+'" data-opt="'+j+'" value="'+esc(options[j]||'')+'" placeholder="Option '+String.fromCharCode(65+j)+'"><button type="button" class="btn ghost" onclick="setExamCorrect('+i+','+j+')">'+(String(q.correctAnswer||'')===String(options[j]||'')?'✓ Correct':'Set correct')+'</button></div>').join('')+'</div>':
    type==='TRUE_FALSE'?'<div class="answer-list"><label class="answer-option"><input type="radio" name="correct-'+i+'" '+(q.correctAnswer==='TRUE'?'checked':'')+' onchange="examDraft['+i+'].correctAnswer=\'TRUE\'"> TRUE</label><label class="answer-option"><input type="radio" name="correct-'+i+'" '+(q.correctAnswer==='FALSE'?'checked':'')+' onchange="examDraft['+i+'].correctAnswer=\'FALSE\'"> FALSE</label></div>':
    '<label>Correct answer (optional)<input data-qshort="'+i+'" value="'+esc(q.correctAnswer||'')+'" placeholder="Exact answer for automatic grading"></label>';
  return '<article class="card exam-question question-editor" data-qindex="'+i+'"><div class="head"><div><span class="question-number">Question '+(i+1)+'</span><h3>'+esc(q.questionText||'')+'</h3></div><button type="button" class="btn danger" onclick="removeExamQuestion('+i+')">Remove</button></div><label>Question<textarea data-qtext="'+i+'" rows="3" placeholder="Write the question...">'+esc(q.questionText||'')+'</textarea></label><div class="grid c2"><label>Type<select data-qtype="'+i+'" onchange="examTypeChanged('+i+',this.value)"><option value="MCQ" '+(type==='MCQ'?'selected':'')+'>Multiple choice</option><option value="TRUE_FALSE" '+(type==='TRUE_FALSE'?'selected':'')+'>True / False</option><option value="SHORT" '+(type==='SHORT'?'selected':'')+'>Short answer</option></select></label><label>Points<input type="number" min="0.5" step="0.5" data-qpoints="'+i+'" value="'+Number(q.points||1)+'"></label></div>'+optionFields+'</article>';
}
function renderExamQuestions(){const root=$('#examQuestions');if(root)root.innerHTML=examDraft.map(examQuestionHTML).join('')||'<div class="empty">No questions yet. Add one.</div>'}
function addExamQuestion(){collectExamQuestions();examDraft.push({questionText:'',questionType:'MCQ',options:['','','',''],correctAnswer:'',points:1});renderExamQuestions()}
function removeExamQuestion(i){collectExamQuestions();if(examDraft.length<=1)return toast('An exam needs at least one question');examDraft.splice(i,1);renderExamQuestions()}
function setExamCorrect(i,j){collectExamQuestions();examDraft[i].correctAnswer=String(examDraft[i].options[j]||'').trim();renderExamQuestions()}
function examTypeChanged(i,type){collectExamQuestions();examDraft[i].questionType=type;examDraft[i].correctAnswer=type==='TRUE_FALSE'?'TRUE':'';if(type==='MCQ'&&examDraft[i].options.length<4)examDraft[i].options=['','','',''];renderExamQuestions()}
function collectExamQuestions(){
  document.querySelectorAll('[data-qindex]').forEach(card=>{
    const i=Number(card.dataset.qindex);if(!examDraft[i])return;
    examDraft[i].questionText=card.querySelector('[data-qtext]')?.value?.trim()||'';
    examDraft[i].points=Number(card.querySelector('[data-qpoints]')?.value||1);
    const type=card.querySelector('[data-qtype]')?.value||examDraft[i].questionType;examDraft[i].questionType=type;
    if(type==='MCQ'){
      examDraft[i].options=[...card.querySelectorAll('[data-qopt="'+i+'"]')].map(x=>x.value.trim()).filter(Boolean);
    }else if(type==='SHORT') examDraft[i].correctAnswer=card.querySelector('[data-qshort]')?.value?.trim()||'';
  });
}
async function examEdit(id){
  let x=S.exams.find(a=>Number(a.id)===Number(id))||{}, questions=[];
  if(id){try{const d=await api('/api/exams/'+id+'/edit');x=d.exam;questions=(d.questions||[]).map(examDraftFromQuestion)}catch(e){return toast(e.message)}}
  examDraft=questions.length?questions:[{questionText:'',questionType:'MCQ',options:['','','',''],correctAnswer:'',points:1}];
  modal('<div class="modalhead"><h2>'+(id?'Edit exam':'Create exam')+'</h2><button class="close" onclick="b4Close()">×</button></div><form class="form" onsubmit="saveExam(event,'+(id||'null')+')"><label>Title<input id="et" value="'+esc(x.title||'')+'" required></label><label>Subject<select id="es">'+S.subjects.map(s=>'<option value="'+s.id+'" '+(Number(s.id)===Number(x.subject_id)?'selected':'')+'>'+esc(s.name)+'</option>').join('')+'</select></label><label>Description<textarea id="ed" rows="3">'+esc(x.description||'')+'</textarea></label><div class="grid c2"><label>Start<input id="est" type="datetime-local" value="'+examInputDate(x.starts_at)+'"></label><label>Deadline<input id="een" type="datetime-local" value="'+examInputDate(x.ends_at)+'"></label></div><label>Time limit (minutes)<input id="dur" type="number" min="1" value="'+esc(x.duration_minutes||'')+'" placeholder="Optional"></label><div class="head"><h3>Questions</h3><button type="button" class="btn ghost" onclick="addExamQuestion()">＋ Add question</button></div><div id="examQuestions"></div><button class="btn primary">Save exam</button></form>');
  renderExamQuestions();
}
async function saveExam(e,id){
  e.preventDefault();collectExamQuestions();
  const qs=examDraft.map(q=>({questionText:q.questionText,questionType:q.questionType,options:q.questionType==='MCQ'?q.options:[],correctAnswer:q.correctAnswer||null,points:Number(q.points||1)})).filter(q=>q.questionText);
  if(!qs.length)return toast('Add at least one question');
  if(qs.some(q=>q.questionType==='MCQ'&&(!q.options||q.options.length<2||!q.correctAnswer)))return toast('Each MCQ needs at least 2 options and a correct answer');
  if(qs.some(q=>q.questionType==='TRUE_FALSE'&&!q.correctAnswer))return toast('Choose TRUE or FALSE for every true/false question');
  const b={title:$('#et').value.trim(),description:$('#ed').value,subjectId:Number($('#es').value)||null,startsAt:$('#est').value||null,endsAt:$('#een').value||null,durationMinutes:Number($('#dur').value)||null,questions:qs};
  try{await api(id?'/api/admin/exams/'+id:'/api/admin/exams',{method:id?'PATCH':'POST',body:JSON.stringify(b)});close();await loadData();render();toast('Exam saved ✓')}catch(x){toast(x.message)}
}
async function startExam(id){
  try{
    const d=await api('/api/exams/'+id+'/start',{method:'POST'});
    const questions=d.questions||[];
    modal('<div class="modalhead"><div><span class="eyebrow">EXAM</span><h2>'+esc(d.exam.title)+'</h2></div><button class="close" onclick="b4Close()">×</button></div><div id="examTimer" class="exam-timer">Loading timer…</div><form class="form exam-run-list" id="examRunForm" onsubmit="submitExam(event,'+id+')">'+questions.map((q,i)=>{
      const type=q.question_type||'MCQ',opts=q.options_json||[];
      let body=type==='MCQ'?'<div class="answer-list">'+opts.map((o,j)=>'<label class="answer-option"><input type="radio" name="q'+q.id+'" value="'+esc(o)+'"> <span>'+esc(o)+'</span></label>').join('')+'</div>':
        type==='TRUE_FALSE'?'<div class="answer-list"><label class="answer-option"><input type="radio" name="q'+q.id+'" value="TRUE"> TRUE</label><label class="answer-option"><input type="radio" name="q'+q.id+'" value="FALSE"> FALSE</label></div>':
        '<textarea name="q'+q.id+'" rows="3" placeholder="Your answer..."></textarea>';
      return '<article class="card exam-run-question"><span class="question-number">Question '+(i+1)+' • '+esc(type)+'</span><h3>'+esc(q.question_text)+'</h3>'+body+'</article>';
    }).join('')+'<button id="examSubmitBtn" class="btn primary">Submit exam</button></form>');
    startExamTimer(d.attempt?.deadline,id);
  }catch(e){toast(e.message)}
}
function startExamTimer(deadline,id){
  clearInterval(window.examTimer);
  const box=$('#examTimer'),end=deadline?new Date(deadline).getTime():null;
  const tick=()=>{
    if(!box)return clearInterval(window.examTimer);
    if(!end){box.textContent='No time limit';return}
    const left=Math.max(0,end-Date.now()),sec=Math.floor(left/1000),m=Math.floor(sec/60),s=sec%60;
    box.textContent='Time remaining • '+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');
    box.classList.toggle('warn',left<60000);box.classList.toggle('danger',left<15000);
    if(left<=0){clearInterval(window.examTimer);toast('Time is over — submitting exam');const form=$('#examRunForm');if(form)submitExam({preventDefault:()=>{}},id,true);}
  };
  tick();window.examTimer=setInterval(tick,1000);
}
async function submitExam(e,id,auto=false){
  e.preventDefault?.();clearInterval(window.examTimer);
  const form=$('#examRunForm'),answers={};
  if(form)form.querySelectorAll('[name^="q"]').forEach(x=>{if((x.type==='radio'&&x.checked)||x.type==='textarea'||(x.type!=='radio'&&x.value?.trim()))answers[x.name.slice(1)]=x.value.trim()});
  try{const d=await api('/api/exams/'+id+'/submit',{method:'POST',body:JSON.stringify({answers})});const pct=Number(d.percent||0);modal('<div class="modalhead"><h2>Exam result</h2><button class="close" onclick="b4Close()">×</button></div><div class="score-wrap"><div class="score-ring" style="--score:'+pct+'"><svg viewBox="0 0 120 120"><circle class="score-bg" cx="60" cy="60" r="50"></circle><circle class="score-value" cx="60" cy="60" r="50" pathLength="100" stroke-dasharray="'+pct+' 100"></circle></svg><div class="score-number">'+pct+'%<small>'+d.score+' / '+d.total+'</small></div></div><p>'+(auto?'Auto-submitted because the time limit ended.':'Submitted successfully.')+'</p></div>')}catch(x){toast(x.message)}
}
async function submissions(id){try{const d=await api('/api/admin/exams/'+id+'/submissions');S.examReview={examId:id,submissions:d.submissions||[]};S.view='exam-review';render();}catch(e){toast(e.message)}}
async function openExamSubmission(examId,attemptId){try{const d=await api('/api/admin/exams/'+examId+'/submissions/'+attemptId);S.examReview={examId,detail:d};S.view='exam-review';render();}catch(e){toast(e.message)}}
function examReviewV(){const r=S.examReview||{};if(r.detail){const d=r.detail;return title('Submission review','Answers submitted by '+esc(d.attempt?.display_name||'Student'),'<button class="btn ghost" onclick="go(\'exams\')">← Back</button>')+'<div class="grid c3 review-summary"><div class="card"><small>Student</small><b>'+esc(d.attempt?.display_name||'—')+'</b></div><div class="card"><small>Score</small><b>'+Number(d.attempt?.score||0)+' / '+Number(d.total||0)+'</b></div><div class="card"><small>Percentage</small><b>'+Number(d.percent||0)+'%</b></div></div><div class="grid review-questions">'+(d.questions||[]).map((q,i)=>'<article class="card review-question"><div class="head"><span class="question-number">Question '+(i+1)+'</span><span class="badge">'+esc(q.question_type)+'</span></div><h3>'+esc(q.question_text)+'</h3><div class="answer-block"><small>Student answer</small><p>'+esc(q.answer_text||'No answer')+'</p></div><div class="answer-block"><small>Correct answer</small><p>'+esc(q.correct_answer||'Not auto-graded')+'</p></div><div class="answer-result '+(q.is_correct===null||q.is_correct===undefined?'not-graded':(q.is_correct?'correct':'incorrect'))+'">'+(q.is_correct===null||q.is_correct===undefined?'• Not auto-graded':(q.is_correct?'✓ Correct':'✕ Incorrect')+' • '+Number(q.points_awarded||0)+' / '+Number(q.points||0))+'</div></article>').join('')+'</div>'}
return title('Exam submissions','Choose a student to review their full answers.','<button class="btn ghost" onclick="go(\'exams\')">← Back</button>')+'<div class="grid review-submissions">'+(r.submissions||[]).map(x=>'<button class="card review-student" onclick="openExamSubmission('+r.examId+','+x.id+')"><div><b>'+esc(x.display_name)+'</b><small>'+esc(x.status||'')+'</small></div><span class="badge">'+Number(x.percent||0)+'%</span></button>').join('')||'<div class="card empty">No submissions yet.</div>'+'</div>'}
async function delAPI(path,msg){if(!confirm('Are you sure?'))return;try{await api(path,{method:'DELETE'});await loadData();render();toast(msg+' ✓')}catch(e){toast(e.message)}}
function searchBind(){const i=$('#search');if(i)i.oninput=()=>{const q=i.value.toLowerCase().trim();if(!q)return;const all=[...S.students,...S.teachers,...S.subjects,...S.assignments,...S.resources];const x=all.find(a=>String(a.display_name||a.name||a.title||'').toLowerCase().includes(q));if(x)toast('Found: '+(x.display_name||x.name||x.title))}}
function toggleTheme(){S.theme=S.theme==='dark'?'light':'dark';localStorage.b4Theme=S.theme;render()}
function setLang(lang){S.lang=lang==='ar'?'ar':'en';localStorage.b4Lang=S.lang;render()}
function toggleLang(){setLang(S.lang==='ar'?'en':'ar')}
function commandCenter(){modal('<div class="modalhead"><h2>More</h2><button class="close" onclick="b4Close()">×</button></div><div class="list"><button class="item" onclick="close();go(\'students\')">Students</button><button class="item" onclick="close();go(\'subjects\')">Subjects</button><button class="item" onclick="close();go(\'schedule\')">Schedule</button><button class="item" onclick="close();go(\'settings\')">Settings</button></div>')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v]');if(b)go(b.dataset.v)});
function cancelReply(){window.replyTo=null;const i=$('#chatInput');if(i){i.value='';i.placeholder='Write a message...'}close()}
window.addEventListener('beforeunload',()=>clearInterval(window.examTimer));
document.addEventListener('DOMContentLoaded',async()=>{document.documentElement.dataset.theme=S.theme;document.documentElement.classList.toggle('dark',S.theme==='dark');$('#theme').onclick=toggleTheme;$('#lang').onclick=toggleLang;$('#install').onclick=()=>toast('Use your browser menu to install B4');$('#mobile').onclick=()=>$('#side').classList.toggle('open');$('#ai').onclick=aiModal;$('#bell').onclick=openNotifications;$('#mobileAlerts').onclick=openNotifications;$('#profile').onclick=()=>S.me?go('settings'):loginModal();searchBind();await loadMe()});
